'use client';
import { useState,useEffect,useRef,useMemo,useId,cloneElement,isValidElement,type ReactElement,type ReactNode,type FormEvent } from 'react';
import { CalendarDays,LayoutDashboard,Users,BookOpen,ChartNoAxesCombined,Wallet,Settings,Search,Plus,ChevronLeft,ChevronRight,ArrowUpRight,ArrowRight,Check,Clock,MoreHorizontal,X,LogOut,Download,Paperclip,Command,PanelLeftClose,Menu,RefreshCw,Archive,GraduationCap,CheckCheck,ExternalLink,SlidersHorizontal,Sun,FileText,AlertCircle } from 'lucide-react';
import { type Data,type Row,type Kind,money,balance,dateLabel,timeLabel,localDate,localTime,labels,overdue } from '../lib/tutor';

const nav=[['overview','Обзор',LayoutDashboard],['calendar','Расписание',CalendarDays],['students','Ученики',Users],['homework','Задания',BookOpen],['progress','Успеваемость',ChartNoAxesCombined],['finance','Оплаты',Wallet]] as const;
const empty:Data={students:[],lessons:[],homework:[],progress:[],payments:[],attachments:[],preferences:{name:'Преподаватель',rate:80000,accent:'forest',font:'sans'}};
const today=()=>localDate(new Date());
const initials=(name:string)=>name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const sortDate=(a:Row,b:Row)=>String(a.start||a.date||a.due).localeCompare(String(b.start||b.date||b.due));
const sorted=(a:Row[])=>[...a].sort(sortDate);
const Badge=({status,late=false}:{status:string;late?:boolean})=><span className={`badge ${late?'late':status}`}>{late?'Просрочено':labels[status]||status}</span>;
const Avatar=({name,index=0}:{name:string;index?:number})=><span className={`avatar tone-${index%4}`}>{initials(name)}</span>;
function Empty({icon:Icon=CalendarDays,title,description,action,label}:{icon?:any;title:string;description:string;action?:()=>void;label?:string}){return <div className="empty"><span className="empty-icon"><Icon size={28}/></span><h3>{title}</h3><p>{description}</p>{action&&<button className="primary" onClick={action}><Plus size={16}/>{label||'Добавить'}</button>}</div>}
function Dialog({title,children,onClose,wide=false,side=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean;side?:boolean}){
 const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();return()=>ref.current?.close()},[]);
 return <dialog ref={ref} aria-label={title} className={`dialog ${side?'drawer':''} ${wide?'wide':''}`} onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===ref.current)onClose()}}><div className="dialog-inner"><header><div><span className="eyebrow">TUTORSPACE</span><h2>{title}</h2></div><button className="icon-button" aria-label="Закрыть" onClick={onClose}><X size={20}/></button></header>{children}</div></dialog>
}
function SparkChart({rows}:{rows:Row[]}){
 const data=sorted(rows);if(data.length<2)return <div className="chart-empty">Добавьте минимум два результата, чтобы увидеть динамику.</div>;
 const pts=data.map((r,i)=>[34+i*532/(data.length-1),150-r.score*1.2]);const line=pts.map(p=>p.join(',')).join(' ');
 return <div className="chart"><svg viewBox="0 0 600 195" role="img" aria-label={`Динамика успеваемости: ${data.map(r=>`${dateLabel(r.date)} — ${r.score}%`).join(', ')}`}><defs><linearGradient id="chartfill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="var(--accent)" stopOpacity=".18"/><stop offset="100%" stopColor="var(--accent)" stopOpacity="0"/></linearGradient></defs>{[0,50,100].map(v=><g key={v}><line x1="34" y1={150-v*1.2} x2="566" y2={150-v*1.2} stroke="var(--line)" strokeDasharray="4 5"/><text x="0" y={154-v*1.2} fill="var(--muted)" fontSize="11">{v}</text></g>)}<polygon points={`34,150 ${line} 566,150`} fill="url(#chartfill)"/><polyline points={line} fill="none" stroke="var(--accent)" strokeWidth="3" strokeLinejoin="round"/>{pts.map((p,i)=><g key={i}><circle cx={p[0]} cy={p[1]} r="5" fill="var(--surface)" stroke="var(--accent)" strokeWidth="3"/><title>{data[i].topic}: {data[i].score}%</title>{(i===0||i===pts.length-1||data.length<7)&&<text x={p[0]} y="180" textAnchor="middle" fill="var(--muted)" fontSize="11">{dateLabel(data[i].date,{day:'numeric',month:'short'})}</text>}</g>)}</svg></div>
}
async function apiFetch(input:RequestInfo|URL,init:RequestInit={}){try{return await fetch(input,{...init,signal:AbortSignal.timeout(25000)})}catch(e){if(e instanceof DOMException&&(e.name==='TimeoutError'||e.name==='AbortError'))throw Error('Сервер не ответил вовремя. Повторите сохранение: защита от дублирования включена.');throw Error('Не удалось связаться с сервером. Проверьте интернет и повторите действие.')}}
function download(name:string,content:string,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

export default function Workspace({user}:{user:{name:string;email:string}}){
 const [data,setData]=useState<Data>(empty),[loading,setLoading]=useState(true),[loadError,setLoadError]=useState(''),[page,setPage]=useState('calendar');
 const [date,setDate]=useState(()=>new Date()),[selectedDay,setSelectedDay]=useState(today()),[view,setView]=useState('month');
 const [query,setQuery]=useState(''),[studentFilter,setStudentFilter]=useState('all'),[showArchive,setShowArchive]=useState(false),[taskFilter,setTaskFilter]=useState('all');
 const [editor,setEditor]=useState<{kind:Kind;row?:Row;defaults?:Row}|null>(null),[detail,setDetail]=useState<{kind:Kind;id:string}|null>(null);
 const [toast,setToast]=useState(''),[searchOpen,setSearchOpen]=useState(false),[quick,setQuick]=useState(false),[menu,setMenu]=useState(false),[busy,setBusy]=useState(false),[help,setHelp]=useState(false);
 const notify=(s:string)=>setToast(s);
 async function load(){setLoadError('');try{const r=await apiFetch('/api/data',{cache:'no-store'}),v=await r.json() as any;if(!r.ok)throw Error(v.error);setData(v)}catch(e){setLoadError(e instanceof Error?e.message:'Нет связи с сервером')}finally{setLoading(false)}}
 useEffect(()=>{load()},[]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)}},[toast]);
 useEffect(()=>{const f=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(v=>!v)}if(e.key==='Escape'){setQuick(false);setMenu(false)}};window.addEventListener('keydown',f);return()=>window.removeEventListener('keydown',f)},[]);
 async function mutate(kind:Kind,row:Row,id?:string,extra:Row={}){const r=await apiFetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,action:'save',data:row,id,...extra})});const v=await r.json() as any;if(!r.ok)throw Error(v.error);await load();return v}
 function open(kind:Kind,row?:Row,defaults?:Row){setQuick(false);setEditor({kind,row,defaults})}
 const student=(id:string)=>data.students.find(s=>s.id===id);
 const active=data.students.filter(s=>!s.archived);
 const lessonMatch=(l:Row)=>studentFilter==='all'||l.studentId===studentFilter;
 const lessons=sorted(data.lessons.filter(lessonMatch));
 const upcoming=lessons.filter(l=>l.status==='planned'&&Date.parse(l.end)>Date.now());
 const prefs=data.preferences;
 const name=prefs.name==='Преподаватель'?user.name:prefs.name;
 const days:Date[]=useMemo(()=>{const first=new Date(date.getFullYear(),date.getMonth(),1),start=new Date(first);start.setDate(1-((first.getDay()+6)%7));return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d})},[date]);
 const inMonth=(s:string)=>{const d=new Date(s);return d.getFullYear()===date.getFullYear()&&d.getMonth()===date.getMonth()};
 const monthLessons=lessons.filter(l=>inMonth(l.start));
 const dayLessons=lessons.filter(l=>localDate(new Date(l.start))===selectedDay);
 const debt=data.students.reduce((n,s)=>n+Math.min(0,balance(data,s.id)),0);
 const due=data.homework.filter(h=>h.status!=='reviewed');
 const dueSoon=due.filter(h=>Date.parse(h.due)<Date.now()+48*3600000);
 const thisMonthIncome=data.payments.filter(p=>inMonth(p.date)).reduce((a,p)=>a+p.amount,0);
 const match=(s:string)=>s.toLowerCase().includes(query.toLowerCase().trim());
 const currentTitle=nav.find(x=>x[0]===page)?.[1]||'Настройки';
 const monthText=date.toLocaleDateString('ru-RU',{month:'long',year:'numeric'}).replace(' г.','');
 const addDefault=()=>open(page==='students'?'students':page==='homework'?'homework':page==='progress'?'progress':page==='finance'?'payments':'lessons');
 async function seed(){
  setBusy(true);try{const s=await mutate('students',{name:'Алексей · пример',level:'9 класс',goal:'Подготовка к ОГЭ по математике',notes:'Демонстрационный ученик. Можно архивировать после знакомства.',rate:80000});
   const now=new Date(),base=new Date(now.getFullYear(),now.getMonth(),1,17,0);let done=0;
   for(let i=0;i<32;i++){const d=new Date(base);d.setDate(i+1);if(d.getMonth()!==base.getMonth())break;if(![1,5].includes(d.getDay()))continue;const past=d.getTime()<Date.now();await mutate('lessons',{studentId:s.id,start:d.toISOString(),duration:60,subject:'Математика',topic:past?'Линейные уравнения':'Квадратные уравнения',status:past?'done':'planned',price:80000});if(past)done++}
   await mutate('homework',{studentId:s.id,title:'Квадратные уравнения · практика',description:'Решить задания 1–8. Записать решение и проверить подстановкой.',due:new Date(Date.now()+3*86400000).toISOString(),status:'assigned'});
   for(const [i,score] of [55,68,82].entries())await mutate('progress',{studentId:s.id,date:new Date(Date.now()-(14-i*7)*86400000).toISOString(),topic:['Уравнения','Функции','Итоговая практика'][i],type:'Тест',score});
   if(done)await mutate('payments',{studentId:s.id,date:new Date().toISOString(),amount:Math.max(1,done-1)*80000,notes:'Демонстрационная оплата'});notify('Пример добавлен. Все записи помечены демонстрационным учеником.');
  }catch(e){notify(e instanceof Error?e.message:'Не удалось добавить пример')}finally{setBusy(false)}
 }
 const lessonCard=(l:Row,compact=false)=><button key={l.id} className={`lesson-event ${l.status} ${compact?'compact':''}`} onClick={()=>setDetail({kind:'lessons',id:l.id})}><span className="event-time">{timeLabel(l.start)}{l.status==='done'&&<Check size={12}/>}</span><strong>{student(l.studentId)?.name||'Ученик'}</strong>{!compact&&<span className="event-topic">{l.topic||l.subject}</span>}</button>;
 const agenda=<aside className="agenda"><div className="agenda-heading"><div><span className="eyebrow">В ФОКУСЕ</span><h3>{dateLabel(selectedDay)}</h3></div><span className="count">{dayLessons.length}</span></div>{dayLessons.length?dayLessons.map(l=><button className="agenda-event" key={l.id} onClick={()=>setDetail({kind:'lessons',id:l.id})}><div className="agenda-time">{timeLabel(l.start)}<span>{timeLabel(l.end)}</span></div><div className="agenda-description"><span className={`status-line ${l.status}`}/><strong>{student(l.studentId)?.name}</strong><p>{l.topic||l.subject}</p><div className="agenda-meta"><span>{l.duration} мин · {money(l.price)}</span><Badge status={l.status}/></div></div></button>):<div className="quiet-day"><Sun size={32}/><strong>Есть время для нового</strong><p>На этот день занятий нет.</p><button className="text-button" onClick={()=>open('lessons',undefined,{start:`${selectedDay}T17:00`})}>Запланировать <ArrowRight size={14}/></button></div>}<div className="agenda-bottom"><div className="section-title"><h4>Ближайшие задания</h4><button className="icon-button" aria-label="Все задания" onClick={()=>setPage('homework')}><ArrowUpRight size={17}/></button></div>{sorted(due).slice(0,3).map(h=><button className="mini-task" key={h.id} onClick={()=>setDetail({kind:'homework',id:h.id})}><span className={`task-dot ${overdue(h)?'late':''}`}/><span><strong>{h.title}</strong><small>{student(h.studentId)?.name} · до {dateLabel(h.due,{day:'numeric',month:'short'})}</small></span></button>)}{!due.length&&<p className="muted small">Все задания проверены. Отличная работа.</p>}</div></aside>;

 return <div className={`app-shell theme-${prefs.accent||'forest'} font-${prefs.font||'sans'}`}>
  <aside className={`sidebar ${menu?'mobile-open':''}`}><div className="sidebar-top"><button className="brand" onClick={()=>setPage('calendar')}>tutor<span>space</span><i>✳︎</i></button><button className="icon-button mobile-only" aria-label="Закрыть меню" onClick={()=>setMenu(false)}><X size={18}/></button></div><div className="workspace-label"><span className="workspace-square">М</span><div>Мое пространство<small>Частная практика</small></div><span className="tiny-dot"/></div><div className="nav-label">РАБОТА</div><nav>{nav.map(([key,label,Icon])=><button key={key} className={page===key?'nav-item active':'nav-item'} onClick={()=>{setPage(key);setQuery('');setMenu(false)}}><Icon size={19}/><span>{label}</span>{key==='homework'&&due.length>0&&<span className="nav-count">{due.length}</span>}{key==='calendar'&&<span className="nav-short">ПН / ПТ</span>}</button>)}</nav><div className="sidebar-spacer"/><div className="practice-note"><span className="asterisk">✳︎</span><h4>Все идет по плану</h4><p>{upcoming.length?`Впереди ${upcoming.length} занятий. Найдется место и для отдыха.`:'Ваше расписание начинается с первого занятия.'}</p><button onClick={()=>{setPage('calendar');setDate(new Date());setSelectedDay(today())}}>К расписанию <ArrowUpRight size={14}/></button></div><button className={`nav-item ${page==='settings'?'active':''}`} onClick={()=>{setPage('settings');setMenu(false)}}><Settings size={19}/>Настройки</button><div className="sidebar-profile"><Avatar name={name}/><div><strong>{name}</strong><small>Преподаватель математики</small></div><a href="/signout-with-chatgpt?return_to=%2F" target="_top" aria-label="Выйти" title="Выйти"><LogOut size={16}/></a></div></aside>
  {menu&&<button className="menu-overlay" aria-label="Закрыть меню" onClick={()=>setMenu(false)}/>}
  <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-only" aria-label="Открыть меню" onClick={()=>setMenu(true)}><Menu size={20}/></button><span>Мое пространство</span><span className="slash">/</span><strong>{currentTitle}</strong></div><div className="topbar-actions"><button className="search-trigger" onClick={()=>{setQuery('');setSearchOpen(true)}}><Search size={16}/><span>Быстрый поиск</span><kbd>⌘ K</kbd></button><span className="topbar-divider"/><button className="icon-button" aria-label="О приложении" onClick={()=>setHelp(true)}><FileText size={18}/></button><button className="profile-dot" onClick={()=>setPage('settings')} aria-label="Настройки профиля">{initials(name)}</button></div></header>
  <main className="main-content"><div className="page-heading"><div><div className="eyebrow">{new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</div><h1>{page==='overview'?'Хороший день для знаний':currentTitle}<span className="heading-dot">.</span></h1><p>{page==='calendar'?'У каждого занятия — свое время.':page==='overview'?'Все важное о вашей практике сегодня.':page==='students'?'Люди, которым вы помогаете двигаться вперед.':page==='homework'?'От первого задания до уверенного решения.':page==='progress'?'Маленькие шаги складываются в заметный результат.':page==='finance'?'Занятия, поступления и баланс без ручных подсчетов.':'Ваш ритм, ваш стиль, ваше пространство.'}</p></div>{page!=='settings'&&<div className="quick-wrap"><button className="primary" onClick={addDefault}><Plus size={18}/>{page==='students'?'Новый ученик':page==='homework'?'Новое задание':page==='progress'?'Новый результат':page==='finance'?'Записать оплату':'Новое занятие'}</button><button className="quick-arrow" onClick={()=>setQuick(!quick)} aria-label="Другие действия"><MoreHorizontal size={19}/></button>{quick&&<div className="quick-menu">{([['students','Добавить ученика'],['lessons','Добавить занятие'],['homework','Выдать задание'],['payments','Записать оплату'],['progress','Добавить результат']] as [Kind,string][]).map(([k,v])=><button key={k} onClick={()=>open(k)}><Plus size={15}/>{v}</button>)}</div>}</div>}</div>
  {loadError&&<div className="error-banner" role="alert"><AlertCircle size={18}/>{loadError}<button onClick={load}>Повторить</button></div>}
  {loading?<div className="loading-state"><RefreshCw size={26}/><p>Открываем ваше пространство…</p></div>:<>
  {(page==='calendar'||page==='overview')&&<div className="stats"><div className="stat"><div><span>Ближайшие 48 часов</span><CalendarDays size={17}/></div><strong>{upcoming.filter(l=>Date.parse(l.start)<Date.now()+48*3600000).length}<small>занятий</small></strong><span className="stat-foot">В вашем расписании</span></div><div className="stat"><div><span>Ученики</span><Users size={17}/></div><strong>{active.length}<small>активных</small></strong><button className="stat-foot" onClick={()=>setPage('students')}>Открыть список <ArrowUpRight size={13}/></button></div><div className="stat"><div><span>Задания к проверке</span><BookOpen size={17}/></div><strong>{dueSoon.length}<small>ближайших</small></strong><span className="stat-foot">{due.filter(overdue).length?`${due.filter(overdue).length} просрочено`:'Всё под контролем'}</span></div><div className="stat accent-stat"><div><span>Оплачено за месяц</span><Wallet size={17}/></div><strong>{money(thisMonthIncome)}</strong><span className="stat-foot">{monthText}</span></div></div>}
  {!data.students.length&&!loadError&&<div className="welcome-strip"><span className="welcome-symbol">✳︎</span><div><strong>Начнем с вашего первого ученика</strong><p>Добавьте его сами или познакомьтесь с приложением на примере.</p></div><button className="secondary" disabled={busy} onClick={seed}>{busy?'Добавляем пример…':'Посмотреть на примере'}<ArrowUpRight size={15}/></button></div>}
  {page==='calendar'&&<section className="calendar-section"><div className="calendar-toolbar"><div className="month-switch"><h2>{monthText}</h2><div className="arrow-group"><button className="icon-button" aria-label="Предыдущий период" onClick={()=>{const d=new Date(date);view==='week'?d.setDate(d.getDate()-7):d.setMonth(d.getMonth()-1,1);setDate(d)}}><ChevronLeft size={17}/></button><button className="icon-button" aria-label="Следующий период" onClick={()=>{const d=new Date(date);view==='week'?d.setDate(d.getDate()+7):d.setMonth(d.getMonth()+1,1);setDate(d)}}><ChevronRight size={17}/></button></div><button className="today-button" onClick={()=>{setDate(new Date());setSelectedDay(today())}}>Сегодня</button></div><div className="calendar-tools"><select aria-label="Фильтр по ученику" value={studentFilter} onChange={e=>setStudentFilter(e.target.value)}><option value="all">Все ученики</option>{data.students.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><div className="segmented">{[['month','Месяц'],['week','Неделя'],['list','Список']].map(([k,v])=><button key={k} aria-pressed={view===k} className={view===k?'selected':''} onClick={()=>setView(k)}>{v}</button>)}</div></div></div><div className="calendar-body"><div className="calendar-main">{view==='month'?<><div className="weekdays">{['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map((d,i)=><span key={d} className={i>4?'weekend':''}>{d}</span>)}</div><div className="month-grid">{days.map(d=>{const key=localDate(d),events=lessons.filter(l=>localDate(new Date(l.start))===key),outside=d.getMonth()!==date.getMonth();return <div key={key} className={`day-cell ${outside?'outside':''} ${selectedDay===key?'chosen':''} ${key===today()?'is-today':''}`}><div className="day-top"><button aria-label={`Выбрать ${dateLabel(key)}`} className="day-number" onClick={()=>setSelectedDay(key)}>{d.getDate()}</button><button className="day-add" aria-label={`Добавить занятие ${dateLabel(key)}`} onClick={()=>{setSelectedDay(key);open('lessons',undefined,{start:`${key}T17:00`})}}><Plus size={13}/></button></div><div className="day-events">{events.slice(0,3).map(l=>lessonCard(l,true))}{events.length>3&&<button className="more-events" onClick={()=>setSelectedDay(key)}>Еще {events.length-3}</button>}</div></div>})}</div></>:view==='week'?<div className="week-grid">{Array.from({length:7},(_,i)=>{const d=new Date(date);d.setDate(date.getDate()-((date.getDay()+6)%7)+i);const key=localDate(d);return <div className="week-column" key={key}><button className={`week-head ${key===today()?'current':''}`} onClick={()=>setSelectedDay(key)}><small>{d.toLocaleDateString('ru-RU',{weekday:'short'})}</small><strong>{d.getDate()}</strong></button>{lessons.filter(l=>localDate(new Date(l.start))===key).map(l=>lessonCard(l))}<button className="week-add" aria-label={`Добавить занятие ${dateLabel(key)}`} onClick={()=>open('lessons',undefined,{start:`${key}T17:00`})}><Plus size={16}/></button></div>})}</div>:<div className="calendar-list">{monthLessons.length?monthLessons.map(l=><button className="list-lesson" key={l.id} onClick={()=>setDetail({kind:'lessons',id:l.id})}><div className="list-date"><strong>{new Date(l.start).getDate()}</strong><small>{dateLabel(l.start,{weekday:'short'})}</small></div><span className="list-time">{timeLabel(l.start)}</span><div className="list-person"><strong>{student(l.studentId)?.name}</strong><small>{l.topic||l.subject}</small></div><Badge status={l.status}/><span>{money(l.price)}</span><ArrowUpRight size={16}/></button>):<Empty title="Месяц открыт для планов" description="Добавьте первое занятие в расписание." action={()=>open('lessons')}/>}</div>}<div className="calendar-footer"><div className="legend"><span><i className="legend-planned"/>Запланировано</span><span><i className="legend-done"/>Проведено</span><span><i className="legend-cancelled"/>Отменено</span></div><span>{monthLessons.length} занятий в месяце · время {Intl.DateTimeFormat().resolvedOptions().timeZone}</span></div></div>{agenda}</div></section>}
  {page==='overview'&&<div className="overview-grid"><section className="panel"><div className="section-title"><div><span className="eyebrow">НА ПОВЕСТКЕ</span><h2>Ближайшие занятия</h2></div><button className="text-button" onClick={()=>setPage('calendar')}>Календарь <ArrowRight size={15}/></button></div>{upcoming.slice(0,6).map(l=><button className="overview-lesson" key={l.id} onClick={()=>setDetail({kind:'lessons',id:l.id})}><span className="overview-day">{dateLabel(l.start,{day:'numeric',month:'short'})}<small>{timeLabel(l.start)}</small></span><Avatar name={student(l.studentId)?.name||''}/><div><strong>{student(l.studentId)?.name}</strong><small>{l.topic||l.subject} · {l.duration} мин</small></div><ArrowUpRight size={17}/></button>)}{!upcoming.length&&<Empty title="Новые планы впереди" description="Назначьте следующее занятие." action={()=>open('lessons')}/>}</section><section className="panel"><div className="section-title"><h2>Требует внимания</h2><span className="count">{dueSoon.length}</span></div>{sorted(dueSoon).slice(0,5).map(h=><button className="attention-task" key={h.id} onClick={()=>setDetail({kind:'homework',id:h.id})}><BookOpen size={18}/><div><strong>{h.title}</strong><small>{student(h.studentId)?.name} · {dateLabel(h.due)}</small></div><Badge status={h.status} late={overdue(h)}/></button>)}{!dueSoon.length&&<div className="quiet-day"><CheckCheck size={32}/><strong>Можно выдохнуть</strong><p>Срочных заданий нет.</p></div>}<div className="balance-note"><span>Общая задолженность</span><strong>{money(-debt)}</strong><button className="text-button" onClick={()=>setPage('finance')}>Посмотреть оплаты <ArrowRight size={14}/></button></div></section></div>}
  {page==='students'&&<section className="panel"><div className="section-title"><div className="input-search"><Search size={17}/><input placeholder="Найти ученика" aria-label="Поиск учеников" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="segmented"><button className={!showArchive?'selected':''} onClick={()=>setShowArchive(false)}>Активные · {active.length}</button><button className={showArchive?'selected':''} onClick={()=>setShowArchive(true)}>Архив · {data.students.length-active.length}</button></div></div><div className="student-grid">{data.students.filter(s=>!!s.archived===showArchive&&match(s.name)).map((s,i)=><button className="student-card" key={s.id} onClick={()=>setDetail({kind:'students',id:s.id})}><div className="student-card-top"><Avatar name={s.name} index={i}/><ArrowUpRight size={18}/></div><h3>{s.name}</h3><span className="muted">{s.level||'Уровень не указан'}</span><p>{s.goal||'Цель обучения пока не указана'}</p><div className="student-card-foot"><span>{money(s.rate)} / час</span><strong className={balance(data,s.id)<0?'negative':'positive'}>{balance(data,s.id)<0?'Долг ':balance(data,s.id)>0?'Аванс ':''}{money(Math.abs(balance(data,s.id)))}</strong></div></button>)}</div>{!data.students.filter(s=>!!s.archived===showArchive&&match(s.name)).length&&<Empty icon={Users} title={query?'Никого не нашли':showArchive?'Архив пуст':'Ваш первый ученик'} description={query?'Попробуйте другую часть имени.':'Здесь будут карточки, история занятий и заметки.'} action={!showArchive&&!query?()=>open('students'):undefined} label="Добавить ученика"/>}</section>}
  {page==='homework'&&<><div className="filter-row"><div className="segmented">{[['all','Все'],['open','В работе'],['late','Просроченные'],['reviewed','Проверенные']].map(([k,v])=><button key={k} className={taskFilter===k?'selected':''} onClick={()=>setTaskFilter(k)}>{v}</button>)}</div><select aria-label="Ученик для заданий" value={studentFilter} onChange={e=>setStudentFilter(e.target.value)}><option value="all">Все ученики</option>{data.students.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></div><div className="homework-grid">{sorted(data.homework).filter(h=>(studentFilter==='all'||h.studentId===studentFilter)&&(taskFilter==='all'||taskFilter==='open'&&h.status!=='reviewed'||taskFilter==='late'&&overdue(h)||taskFilter==='reviewed'&&h.status==='reviewed')).map(h=><button className="homework-card" key={h.id} onClick={()=>setDetail({kind:'homework',id:h.id})}><div className="section-title"><BookOpen size={20}/><Badge status={h.status} late={overdue(h)}/></div><h3>{h.title}</h3><p>{h.description||'Без дополнительного описания'}</p><div className="homework-card-foot"><span>{student(h.studentId)?.name}</span><small><Clock size={13}/>до {dateLabel(h.due,{day:'numeric',month:'short'})}</small></div></button>)}</div>{!data.homework.filter(h=>(studentFilter==='all'||h.studentId===studentFilter)&&(taskFilter==='all'||taskFilter==='open'&&h.status!=='reviewed'||taskFilter==='late'&&overdue(h)||taskFilter==='reviewed'&&h.status==='reviewed')).length&&<section className="panel"><Empty icon={BookOpen} title="Здесь пока нет заданий" description="Выдайте домашнюю работу или измените фильтр." action={()=>open('homework')} label="Выдать задание"/></section>}</>}
  {page==='progress'&&<section className="panel"><div className="section-title"><h2>Динамика результатов</h2><select aria-label="Ученик для графика" value={studentFilter==='all'?(active[0]?.id||''):studentFilter} onChange={e=>setStudentFilter(e.target.value)}>{data.students.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></div>{(()=>{const id=studentFilter==='all'?active[0]?.id:studentFilter,rows=data.progress.filter(p=>p.studentId===id);return <><SparkChart rows={rows}/><div className="table-wrap"><table><thead><tr><th>Дата</th><th>Тема</th><th>Вид работы</th><th>Результат</th><th/></tr></thead><tbody>{sorted(rows).reverse().map(p=><tr key={p.id}><td>{dateLabel(p.date)}</td><td>{p.topic}</td><td>{p.type}</td><td><span className="score">{p.score}%</span></td><td><button className="icon-button" aria-label="Изменить результат" onClick={()=>open('progress',p)}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div>{!rows.length&&<Empty icon={ChartNoAxesCombined} title="Первый результат впереди" description="Запишите балл за тест или контрольную." action={()=>open('progress')} label="Добавить результат"/>}</>})()}</section>}
  {page==='finance'&&<><div className="finance-stats"><div className="finance-stat"><span>Начислено за проведенные занятия</span><strong>{money(data.lessons.filter(l=>l.status==='done').reduce((n,l)=>n+l.price,0))}</strong></div><div className="finance-stat"><span>Всего получено</span><strong className="positive">{money(data.payments.reduce((n,p)=>n+p.amount,0))}</strong></div><div className="finance-stat"><span>Задолженность учеников</span><strong className={debt<0?'negative':''}>{money(-debt)}</strong></div></div><section className="panel"><div className="section-title"><h2>Взаиморасчеты</h2><button className="secondary" onClick={()=>{const q=(v:any)=>'"'+String(typeof v==='string'&&/^[=+@-]/.test(v)?'’'+v:v??'').replaceAll('"','""')+'"';download('TutorSpace-балансы.csv',[['Ученик','Начислено, руб.','Оплачено, руб.','Баланс, руб.'],...data.students.map(s=>[s.name,data.lessons.filter(l=>l.studentId===s.id&&l.status==='done').reduce((n,l)=>n+l.price,0)/100,data.payments.filter(p=>p.studentId===s.id).reduce((n,p)=>n+p.amount,0)/100,balance(data,s.id)/100])].map(r=>r.map(q).join(';')).join('\r\n'),'text/csv;charset=utf-8')}}><Download size={15}/>Скачать CSV</button></div><div className="table-wrap"><table><thead><tr><th>Ученик</th><th>Проведено занятий</th><th>Баланс</th><th/></tr></thead><tbody>{data.students.map(s=><tr key={s.id}><td><button className="person-button" onClick={()=>setDetail({kind:'students',id:s.id})}><Avatar name={s.name}/><span>{s.name}{!!s.archived&&<small>В архиве</small>}</span></button></td><td>{data.lessons.filter(l=>l.studentId===s.id&&l.status==='done').length}</td><td><span className={balance(data,s.id)<0?'negative':'positive'}>{money(balance(data,s.id))}</span><small className="block muted">{balance(data,s.id)<0?'Задолженность':balance(data,s.id)>0?'Аванс':'Расчеты закрыты'}</small></td><td><button className="text-button" onClick={()=>open('payments',undefined,{studentId:s.id})}>Записать оплату <Plus size={14}/></button></td></tr>)}</tbody></table></div>{!data.students.length&&<Empty icon={Wallet} title="Расчеты начнутся с первого урока" description="Добавьте ученика, проведите занятие и запишите оплату."/>}</section><section className="panel payment-history"><div className="section-title"><h2>История поступлений</h2></div>{sorted(data.payments).reverse().map(p=><button className="payment-row" key={p.id} onClick={()=>open('payments',p)}><span className="payment-icon"><ArrowUpRight size={17}/></span><div><strong>{student(p.studentId)?.name}</strong><small>{dateLabel(p.date)}{p.notes?' · '+p.notes:''}</small></div><strong className="positive">+{money(p.amount)}</strong></button>)}{!data.payments.length&&<p className="muted">Поступлений пока нет.</p>}</section></>}
  {page==='settings'&&<SettingsForm data={data} user={user} notify={notify} reload={load}/>}
  <footer className="app-footer"><span>tutorspace <i>✳︎</i> личная практика, в порядке</span><span>Версия 1.0.0 <span className="footer-dot">·</span> {user.email}</span></footer>
  </>}
  </main></div>
  {toast&&<div className="toast" role="status"><Check size={17}/><span>{toast}</span><button className="icon-button" aria-label="Закрыть уведомление" onClick={()=>setToast('')}><X size={15}/></button></div>}
  {editor&&<Editor key={`${editor.kind}-${editor.row?.id||'new'}`} {...editor} data={data} onClose={()=>setEditor(null)} onSave={async(row,extra,file)=>{const result=await mutate(editor.kind,row,editor.row?.id,extra);if(file){const f=new FormData();f.set('file',file);f.set('homeworkId',result.id);try{const r=await apiFetch('/api/files',{method:'POST',body:f}),v=await r.json() as any;if(!r.ok)throw Error(v.error);await load()}catch(e){setEditor({kind:'homework',row:{...row,id:result.id,created:editor.row?.created||new Date().toISOString()}});throw Error(`Задание сохранено, файл не загружен: ${e instanceof Error?e.message:'повторите загрузку'}`)}}setEditor(null);notify(result.count>1?`Создано занятий: ${result.count}`:'Сохранено')}}/>}
  {detail&&<Details kind={detail.kind} row={data[detail.kind].find(x=>x.id===detail.id)} data={data} onClose={()=>setDetail(null)} onEdit={(kind,row)=>{setDetail(null);open(kind,row)}} onAdd={(kind,defaults)=>{setDetail(null);open(kind,undefined,defaults)}} onChange={async(kind,row)=>{try{await mutate(kind,row,row.id);notify('Изменения сохранены')}catch(e){notify(e instanceof Error?e.message:'Ошибка')}}}/>}
  {searchOpen&&<Dialog title="Быстрый поиск" onClose={()=>setSearchOpen(false)}><div className="input-search palette-input"><Search size={18}/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ученик, тема или задание…" aria-label="Быстрый поиск"/></div><div className="search-results">{data.students.filter(s=>match(s.name)).slice(0,6).map(s=><button key={s.id} onClick={()=>{setSearchOpen(false);setDetail({kind:'students',id:s.id})}}><Avatar name={s.name}/><span><strong>{s.name}</strong><small>Ученик · {s.level}</small></span><ArrowUpRight size={16}/></button>)}{data.lessons.filter(l=>query.trim()&&match(l.topic+' '+(student(l.studentId)?.name||''))).slice(0,5).map(l=><button key={l.id} onClick={()=>{setSearchOpen(false);setDetail({kind:'lessons',id:l.id})}}><CalendarDays size={20}/><span><strong>{l.topic||l.subject}</strong><small>{student(l.studentId)?.name} · {dateLabel(l.start)}</small></span><ArrowUpRight size={16}/></button>)}{data.homework.filter(h=>query.trim()&&match(h.title)).slice(0,5).map(h=><button key={h.id} onClick={()=>{setSearchOpen(false);setDetail({kind:'homework',id:h.id})}}><BookOpen size={20}/><span><strong>{h.title}</strong><small>Домашнее задание</small></span><ArrowUpRight size={16}/></button>)}{!data.students.filter(s=>match(s.name)).length&&!data.lessons.some(l=>query.trim()&&match(l.topic+' '+(student(l.studentId)?.name||'')))&&!data.homework.some(h=>query.trim()&&match(h.title))&&<p className="muted">Совпадений нет.</p>}</div></Dialog>}
  {help&&<Dialog title="Ваш TutorSpace" onClose={()=>setHelp(false)}><div className="help-content"><p>Личное рабочее пространство репетитора. Ученики, расписание, задания, результаты и оплаты связаны между собой.</p><dl><dt>Быстрое добавление</dt><dd>Наведите курсор на дату в календаре и нажмите «+».</dd><dt>Повторения</dt><dd>В новом занятии включите повторение и выберите понедельник и пятницу. Часовой пояс повторений — Москва.</dd><dt>Баланс</dt><dd>Оплаты минус стоимость проведенных занятий. Отрицательный баланс — долг, положительный — аванс.</dd><dt>Сохранность</dt><dd>Изменения сохраняются на сервере. Резервную копию записей можно скачать в настройках.</dd></dl><small className="muted">TutorSpace 1.0.0 · учебный проект ОПД · 2026</small></div></Dialog>}
 </div>
}

function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){const id=useId(),control=isValidElement(children)&&typeof children.type==='string'&&['input','select','textarea'].includes(children.type);return <div className="field"><label id={id+'label'} htmlFor={control?id:undefined}>{label}</label>{control?cloneElement(children as ReactElement<any>,{id,'aria-describedby':hint?id+'hint':undefined}):<div role="group" aria-labelledby={id+'label'}>{children}</div>}{hint&&<small id={id+'hint'}>{hint}</small>}</div>}
function Editor({kind,row,defaults,data,onClose,onSave}:{kind:Kind;row?:Row;defaults?:Row;data:Data;onClose:()=>void;onSave:(row:Row,extra:Row,file:File|null)=>Promise<void>}){
 const studentId=row?.studentId||defaults?.studentId||data.students.find(s=>!s.archived)?.id||'';
 const now=new Date();now.setMinutes(0,0,0);now.setHours(now.getHours()+1);
 const init:Row={name:'',phone:'',level:'',goal:'',notes:'',rate:data.preferences.rate??80000,archived:0,studentId,start:localTime(now),duration:60,subject:'Математика',topic:'',status:kind==='homework'?'assigned':'planned',price:data.students.find(s=>s.id===studentId)?.rate??80000,title:'',description:'',due:localTime(new Date(Date.now()+3*86400000)),review:'',link:'',lessonId:'',date:localTime(new Date()),score:0,type:'Тест',amount:80000,...defaults,...row};
 for(const k of ['start','due','date'])if(init[k])init[k]=localTime(new Date(init[k]));
 const requestId=useRef(crypto.randomUUID());
 const [d,setD]=useState<Row>(init),[saving,setSaving]=useState(false),[error,setError]=useState(''),[repeat,setRepeat]=useState(false),[days,setDays]=useState([1,5]),[until,setUntil]=useState(localDate(new Date(Date.now()+90*86400000))),[file,setFile]=useState<File|null>(null);
 const set=(k:string,v:any)=>setD(p=>({...p,[k]:v}));
 const rate=data.students.find(s=>s.id===d.studentId)?.rate??data.preferences.rate??80000;
 const isPastDue=kind==='homework'&&row&&Date.parse(row.due)<Date.now();
 const title=(row?'Изменить ':'')+({students:row?'ученика':'Новый ученик',lessons:row?'занятие':'Новое занятие',homework:row?'задание':'Новое задание',progress:row?'результат':'Новый результат',payments:row?'оплату':'Записать оплату'}[kind]);
 async function submit(e:FormEvent){e.preventDefault();setError('');setSaving(true);try{const v={...d};for(const k of kind==='lessons'?['start']:kind==='homework'?['due']:kind==='payments'||kind==='progress'?['date']:[])v[k]=new Date(v[k]).toISOString();if(repeat&&new Date(until+'T23:59:59+03:00').getTime()<Date.parse(v.start))throw Error('Дата окончания повторений должна быть позже первого занятия');await onSave(v,{requestId:requestId.current,...(repeat?{repeat:{days,until:new Date(until+'T23:59:59+03:00').toISOString()}}:{})},file)}catch(e){setError(e instanceof Error?e.message:'Не удалось сохранить')}finally{setSaving(false)}}
 if(kind!=='students'&&!data.students.length)return <Dialog title={title} onClose={onClose}><Empty icon={Users} title="Сначала добавьте ученика" description="Занятия, задания и оплаты относятся к ученику."/><div className="form-actions"><button className="secondary" onClick={onClose}>Понятно</button></div></Dialog>;
 return <Dialog title={title} onClose={()=>{if(!saving)onClose()}}><form onSubmit={submit} className="editor-form"><div className="form-fields">
 {kind!=='students'&&<Field label="Ученик"><select required value={d.studentId} onChange={e=>{const s=data.students.find(s=>s.id===e.target.value);setD(p=>({...p,studentId:e.target.value,lessonId:'',price:Math.round((s?.rate??80000)*p.duration/60)}))}}>{data.students.filter(s=>!s.archived||s.id===d.studentId).map(s=><option key={s.id} value={s.id}>{s.name}{s.archived?' (архив)':''}</option>)}</select></Field>}
 {kind==='students'&&<><Field label="Имя и фамилия"><input autoFocus required minLength={2} maxLength={120} value={d.name} onChange={e=>set('name',e.target.value)} placeholder="Как зовут ученика"/></Field><div className="form-grid"><Field label="Телефон"><input type="tel" value={d.phone} onChange={e=>set('phone',e.target.value)} placeholder="+7 …"/></Field><Field label="Класс или уровень"><input value={d.level} onChange={e=>set('level',e.target.value)} placeholder="Например, 9 класс"/></Field></div><Field label="Цель обучения"><textarea value={d.goal} onChange={e=>set('goal',e.target.value)} placeholder="Подготовка к ОГЭ, помощь со школьной программой…" rows={2}/></Field><Field label="Стоимость часа, ₽" hint="Ставка используется для новых занятий. История начислений не меняется."><input type="number" min="0" max="1000000" step="0.01" required value={d.rate/100} onChange={e=>set('rate',Math.round(Number(e.target.value)*100))}/></Field></>}
 {kind==='lessons'&&<><div className="form-grid"><Field label="Начало занятия"><input type="datetime-local" required value={d.start} onChange={e=>set('start',e.target.value)}/></Field><Field label="Длительность, минут"><input type="number" min="5" max="1440" step="1" required value={d.duration} onChange={e=>{const n=Number(e.target.value);setD(p=>({...p,duration:n,price:Math.round(rate*n/60)}))}}/></Field></div><div className="form-grid"><Field label="Предмет"><input required value={d.subject} onChange={e=>set('subject',e.target.value)}/></Field><Field label="Стоимость занятия, ₽"><input type="number" min="0" max="1000000" step="0.01" required disabled={row?.status==='done'} value={d.price/100} onChange={e=>set('price',Math.round(Number(e.target.value)*100))}/></Field></div><Field label="Тема занятия"><input value={d.topic} maxLength={200} onChange={e=>set('topic',e.target.value)} placeholder="Например, квадратные уравнения"/></Field><Field label="Статус"><select value={d.status} onChange={e=>set('status',e.target.value)}>{['planned','done','cancelled'].map(v=><option value={v} key={v}>{labels[v]}</option>)}</select></Field>{!row&&<div className="repeat-box"><label className="check-label"><input type="checkbox" checked={repeat} onChange={e=>setRepeat(e.target.checked)}/>Повторять занятие</label>{repeat&&<><div className="weekday-picker">{['Вс','Пн','Вт','Ср','Чт','Пт','Сб'].map((v,i)=><button type="button" aria-pressed={days.includes(i)} className={days.includes(i)?'picked':''} key={i} onClick={()=>setDays(ds=>ds.includes(i)?ds.filter(x=>x!==i):[...ds,i])}>{v}</button>)}</div><Field label="Повторять до" hint="Дни недели и время серии считаются по Москве (UTC+3)."><input type="date" value={until} required min={d.start.slice(0,10)} onChange={e=>setUntil(e.target.value)}/></Field></>}</div>}{row?.series&&<p className="form-note">Это занятие входит в серию. Здесь меняется только выбранное занятие.</p>}</>}
 {kind==='homework'&&<><Field label="Название задания"><input autoFocus value={d.title} required maxLength={200} onChange={e=>set('title',e.target.value)} placeholder="Что нужно сделать"/></Field><Field label="Описание"><textarea rows={3} value={d.description} onChange={e=>set('description',e.target.value)} placeholder="Номера заданий, страницы и требования"/></Field><div className="form-grid"><Field label="Срок сдачи"><input type="datetime-local" required min={row?undefined:localTime(new Date())} value={d.due} onChange={e=>set('due',e.target.value)}/></Field><Field label="Статус"><select value={d.status} onChange={e=>set('status',e.target.value)}>{['assigned','completed','reviewed'].map(v=><option value={v} key={v}>{labels[v]}</option>)}</select></Field></div><Field label="Связанное занятие"><select value={d.lessonId||''} onChange={e=>set('lessonId',e.target.value)}><option value="">Без привязки к занятию</option>{sorted(data.lessons.filter(l=>l.studentId===d.studentId)).reverse().map(l=><option key={l.id} value={l.id}>{dateLabel(l.start)} · {l.topic||l.subject}</option>)}</select></Field><Field label="Ссылка на материалы"><input type="url" value={d.link} onChange={e=>set('link',e.target.value)} placeholder="https://…"/></Field><Field label="Прикрепить файл" hint="Фото, PDF или другой материал до 10 МБ."><input type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/></Field><Field label={d.status==='reviewed'?'Комментарий к проверке *':'Комментарий к проверке'}><textarea required={d.status==='reviewed'} value={d.review} onChange={e=>set('review',e.target.value)} rows={2}/></Field>{isPastDue&&<p className="form-note">Срок задания уже наступил. Можно сохранить прежний срок или назначить новый.</p>}</>}
 {kind==='progress'&&<><Field label="Тема"><input autoFocus required value={d.topic} onChange={e=>set('topic',e.target.value)} placeholder="Тема проверочной работы"/></Field><div className="form-grid"><Field label="Дата"><input type="datetime-local" required value={d.date} onChange={e=>set('date',e.target.value)}/></Field><Field label="Вид работы"><select value={d.type} onChange={e=>set('type',e.target.value)}>{['Тест','Контрольная','Коллоквиум'].map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Результат, %"><input type="number" min="0" max="100" step="1" required value={d.score} onChange={e=>set('score',Number(e.target.value))}/></Field></>}
 {kind==='payments'&&<><div className="form-grid"><Field label="Дата оплаты"><input type="datetime-local" required value={d.date} onChange={e=>set('date',e.target.value)}/></Field><Field label="Сумма, ₽"><input autoFocus type="number" min="0.01" step="0.01" max="1000000" required value={d.amount/100} onChange={e=>set('amount',Math.round(Number(e.target.value)*100))}/></Field></div><div className="payment-preview"><span>Текущий баланс ученика</span><strong>{money(balance(data,d.studentId))}</strong><small>Оплата учитывается вручную. Деньги через приложение не переводятся.</small></div></>}
 {kind!=='homework'&&<Field label="Заметки"><textarea rows={2} value={d.notes} onChange={e=>set('notes',e.target.value)} placeholder="Только для вас"/></Field>}
 {error&&<div role="alert" className="form-error"><AlertCircle size={16}/>{error}</div>}
 </div><div className="form-actions"><span className="muted small">{saving?'Сохраняем на сервере…':'Изменения сохранятся после нажатия'}</span><button type="button" className="secondary" disabled={saving} onClick={onClose}>Отмена</button><button className="primary" type="submit" disabled={saving}>{saving?'Сохранение…':repeat?'Создать серию':'Сохранить'}<Check size={16}/></button></div></form></Dialog>
}

function Details({kind,row,data,onClose,onEdit,onAdd,onChange}:{kind:Kind;row?:Row;data:Data;onClose:()=>void;onEdit:(kind:Kind,row:Row)=>void;onAdd:(kind:Kind,defaults:Row)=>void;onChange:(kind:Kind,row:Row)=>Promise<void>}){
 const [acting,setActing]=useState(false),[tab,setTab]=useState('lessons');
 if(!row)return null;
 const s=kind==='students'?row:data.students.find(s=>s.id===row.studentId),ls=sorted(data.lessons.filter(l=>l.studentId===s?.id)),hs=sorted(data.homework.filter(h=>h.studentId===s?.id)),ps=sorted(data.progress.filter(p=>p.studentId===s?.id));
 const act=async(value:Row)=>{setActing(true);try{await onChange(kind,value)}finally{setActing(false)}};
 return <Dialog title={kind==='students'?row.name:kind==='lessons'?'Детали занятия':row.title||row.topic||'Детали'} onClose={onClose} wide={kind==='students'} side><div className="detail-content">
 {kind==='students'?<><div className="student-profile"><Avatar name={row.name}/><div><strong>{row.level||'Уровень не указан'}</strong><p>{row.phone||'Телефон не указан'}</p></div><button className="secondary" onClick={()=>onEdit('students',row)}>Редактировать</button></div><div className="profile-numbers"><div><span>Проведено занятий</span><strong>{ls.filter(l=>l.status==='done').length}</strong></div><div><span>Стоимость часа</span><strong>{money(row.rate)}</strong></div><div><span>{balance(data,row.id)<0?'Задолженность':'Баланс'}</span><strong className={balance(data,row.id)<0?'negative':'positive'}>{money(balance(data,row.id))}</strong></div></div>{row.goal&&<div className="profile-goal"><span className="eyebrow">ЦЕЛЬ ОБУЧЕНИЯ</span><p>{row.goal}</p></div>}{row.notes&&<p className="notes-text">{row.notes}</p>}<div className="profile-actions"><button className="secondary" disabled={!!row.archived} onClick={()=>onAdd('lessons',{studentId:row.id})}><CalendarDays size={15}/>Занятие</button><button className="secondary" disabled={!!row.archived} onClick={()=>onAdd('homework',{studentId:row.id})}><BookOpen size={15}/>Задание</button><button className="secondary" disabled={!!row.archived} onClick={()=>onAdd('payments',{studentId:row.id})}><Wallet size={15}/>Оплата</button></div><div className="segmented profile-tabs">{[['lessons','Занятия'],['homework','Задания'],['progress','Результаты'],['payments','Оплаты']].map(([k,v])=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{v}</button>)}</div>{tab==='lessons'&&<div>{ls.reverse().map(l=><button className="detail-list" key={l.id} onClick={()=>onEdit('lessons',l)}><span><strong>{dateLabel(l.start)} · {timeLabel(l.start)}</strong><small>{l.topic||l.subject}</small></span><Badge status={l.status}/><span>{money(l.price)}</span></button>)}{!ls.length&&<p className="muted">Занятий пока нет.</p>}</div>}{tab==='homework'&&<div>{hs.map(h=><button className="detail-list" key={h.id} onClick={()=>onEdit('homework',h)}><span><strong>{h.title}</strong><small>До {dateLabel(h.due)}</small></span><Badge status={h.status} late={overdue(h)}/></button>)}{!hs.length&&<p className="muted">Заданий пока нет.</p>}</div>}{tab==='progress'&&<><SparkChart rows={ps}/>{ps.map(p=><button className="detail-list" key={p.id} onClick={()=>onEdit('progress',p)}><span><strong>{p.topic}</strong><small>{dateLabel(p.date)} · {p.type}</small></span><strong className="score">{p.score}%</strong></button>)}<button className="text-button" disabled={!!row.archived} onClick={()=>onAdd('progress',{studentId:row.id})}><Plus size={15}/>Добавить результат</button></>}{tab==='payments'&&<>{sorted(data.payments.filter(p=>p.studentId===row.id)).reverse().map(p=><button className="detail-list" key={p.id} onClick={()=>onEdit('payments',p)}><span><strong>{dateLabel(p.date)}</strong><small>{p.notes}</small></span><strong className="positive">+{money(p.amount)}</strong></button>)}</>}<div className="archive-action"><button className="text-button" disabled={acting} onClick={()=>act({...row,archived:row.archived?0:1})}><Archive size={15}/>{row.archived?'Восстановить ученика':'Архивировать ученика'}</button><small>История занятий и оплат сохранится.</small></div></>:kind==='lessons'?<><div className="detail-person"><Avatar name={s?.name||''}/><div><strong>{s?.name}</strong><small>{row.subject}</small></div><Badge status={row.status}/></div><h3 className="detail-topic">{row.topic||'Тема пока не указана'}</h3><div className="detail-metrics"><div><CalendarDays size={18}/><span>{dateLabel(row.start)}<small>{timeLabel(row.start)}–{timeLabel(row.end)}</small></span></div><div><Clock size={18}/><span>{row.duration} минут<small>Очное занятие</small></span></div><div><Wallet size={18}/><span>{money(row.price)}<small>{row.status==='done'?'Учтено в начислениях':'Начислится после проведения'}</small></span></div></div>{row.notes&&<p className="notes-text">{row.notes}</p>}<div className="detail-actions">{row.status==='planned'&&<button className="primary" disabled={acting} onClick={()=>act({...row,status:'done'})}><CheckCheck size={17}/>Занятие проведено</button>}<button className="secondary" onClick={()=>onEdit('lessons',row)}>Изменить</button></div><div className="related-work"><div className="section-title"><h3>Домашнее задание</h3><button className="text-button" onClick={()=>onAdd('homework',{studentId:row.studentId,lessonId:row.id})}><Plus size={15}/>Выдать</button></div>{data.homework.filter(h=>h.lessonId===row.id).map(h=><button className="detail-list" key={h.id} onClick={()=>onEdit('homework',h)}><strong>{h.title}</strong><Badge status={h.status} late={overdue(h)}/></button>)}{!data.homework.some(h=>h.lessonId===row.id)&&<p className="muted small">К этому занятию пока ничего не прикреплено.</p>}</div>{row.status!=='cancelled'&&<button className="text-button danger" disabled={acting} onClick={()=>{if(confirm('Отменить занятие? Оно сохранится в истории, начисление будет исключено.'))act({...row,status:'cancelled'})}}>Отменить занятие</button>}</>:kind==='homework'?<><div className="detail-person"><Avatar name={s?.name||''}/><div><strong>{s?.name}</strong><small>До {dateLabel(row.due)} · {timeLabel(row.due)}</small></div><Badge status={row.status} late={overdue(row)}/></div><p className="notes-text">{row.description||'Без описания'}</p>{row.link&&<a className="attachment" href={row.link} target="_blank" rel="noopener noreferrer"><ExternalLink size={17}/>Открыть материалы <ArrowUpRight size={15}/></a>}{data.attachments.filter(f=>f.homeworkId===row.id).map(f=><a className="attachment" key={f.id} href={`/api/files?id=${encodeURIComponent(f.id)}`}><Paperclip size={17}/><span>{f.name}<small>{(f.size/1024).toFixed(0)} КБ</small></span><Download size={16}/></a>)}{row.review&&<div className="review-text"><span className="eyebrow">ОБРАТНАЯ СВЯЗЬ</span><p>{row.review}</p>{row.reviewed&&<small>{dateLabel(row.reviewed)}</small>}</div>}<div className="detail-actions">{row.status==='assigned'&&<button className="primary" disabled={acting} onClick={()=>act({...row,status:'completed'})}><Check size={16}/>Отметить выполненным</button>}{row.status==='completed'&&<button className="primary" onClick={()=>onEdit('homework',{...row,status:'reviewed'})}>Проверить работу</button>}<button className="secondary" onClick={()=>onEdit('homework',row)}>Изменить / прикрепить файл</button></div></>:null}
 </div></Dialog>
}

function SettingsForm({data,user,notify,reload}:{data:Data;user:{name:string;email:string};notify:(s:string)=>void;reload:()=>Promise<void>}){
 const [p,setP]=useState(data.preferences),[saving,setSaving]=useState(false),[error,setError]=useState('');
 async function save(e:FormEvent){e.preventDefault();setSaving(true);setError('');try{const r=await apiFetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'preferences',data:p})}),v=await r.json() as any;if(!r.ok)throw Error(v.error);await reload();notify('Настройки сохранены')}catch(e){setError(e instanceof Error?e.message:'Ошибка')}finally{setSaving(false)}}
 return <div className="settings-grid"><form className="panel" onSubmit={save}><span className="eyebrow">ЛИЧНЫЕ НАСТРОЙКИ</span><h2>Ваш профиль</h2><div className="settings-fields"><Field label="Как к вам обращаться"><input value={p.name} maxLength={120} onChange={e=>setP({...p,name:e.target.value})}/></Field><Field label="Аккаунт"><input disabled value={user.email}/></Field><Field label="Стоимость часа по умолчанию, ₽"><input type="number" min="0" max="1000000" step="0.01" required value={p.rate/100} onChange={e=>setP({...p,rate:Math.round(Number(e.target.value)*100)})}/></Field><Field label="Цвет пространства"><div className="theme-picker">{[['forest','Лесной'],['cobalt','Кобальт'],['plum','Сливовый']].map(([v,l])=><button type="button" key={v} className={`theme-chip ${v} ${p.accent===v?'chosen':''}`} onClick={()=>setP({...p,accent:v})}><i/>{l}{p.accent===v&&<Check size={14}/>}</button>)}</div></Field><Field label="Заголовки"><select value={p.font} onChange={e=>setP({...p,font:e.target.value})}><option value="sans">Четкие и современные</option><option value="serif">С книжным характером</option></select></Field>{error&&<p className="form-error" role="alert">{error}</p>}<button className="primary" disabled={saving}>{saving?'Сохраняем…':'Сохранить настройки'}<Check size={16}/></button></div></form><div><section className="panel"><span className="eyebrow">ВАШИ ДАННЫЕ</span><h2>Копия под рукой</h2><p className="muted">Скачайте все записи одним файлом: ученики, занятия, задания, результаты и оплаты. Содержимое вложений скачивается отдельно из заданий.</p><button className="secondary" onClick={()=>download(`TutorSpace-${today()}.json`,JSON.stringify({version:1,exportedAt:new Date().toISOString(),...data},null,2))}><Download size={16}/>Экспортировать записи</button></section><section className="settings-about"><div className="brand">tutor<span>space</span><i>✳︎</i></div><p>Свое пространство для большой работы.</p><small>Версия 1.0.0 · 18 ноября 2026<br/>Учебный проект по основам проектной деятельности.</small><a className="text-button" href="/signout-with-chatgpt?return_to=%2F" target="_top"><LogOut size={15}/>Выйти из аккаунта</a></section></div></div>
}
